CREATE TRIGGER fold_report_contact_erasure AFTER DELETE ON contacts WHEN NOT EXISTS(SELECT 1 FROM runtime_controls WHERE name='restore') BEGIN DELETE FROM analytics_snapshots WHERE id IN(SELECT snapshot_id FROM analytics_snapshot_sources WHERE kind='contact' AND record_id=OLD.id) OR EXISTS(SELECT 1 FROM json_each(analytics_snapshots.body_json,'$.inputs') ref WHERE json_extract(ref.value,'$.type')='contact' AND json_extract(ref.value,'$.id')=OLD.id);END;
CREATE TRIGGER fold_report_company_erasure AFTER DELETE ON companies WHEN NOT EXISTS(SELECT 1 FROM runtime_controls WHERE name='restore') BEGIN DELETE FROM analytics_snapshots WHERE id IN(SELECT snapshot_id FROM analytics_snapshot_sources WHERE kind='company' AND record_id=OLD.id) OR EXISTS(SELECT 1 FROM json_each(analytics_snapshots.body_json,'$.inputs') ref WHERE json_extract(ref.value,'$.type')='company' AND json_extract(ref.value,'$.id')=OLD.id);END;
CREATE TRIGGER fold_report_opportunity_erasure AFTER DELETE ON opportunities WHEN NOT EXISTS(SELECT 1 FROM runtime_controls WHERE name='restore') BEGIN DELETE FROM analytics_snapshots WHERE id IN(SELECT snapshot_id FROM analytics_snapshot_sources WHERE kind='opportunity' AND record_id=OLD.id) OR EXISTS(SELECT 1 FROM json_each(analytics_snapshots.body_json,'$.inputs') ref WHERE json_extract(ref.value,'$.type')='opportunity' AND json_extract(ref.value,'$.id')=OLD.id);END;

